// All triples of forward red additions, at most seven forward red removals.
use std::io::{self,Read};type A=[u32;26];type E=(usize,usize);
fn avail(a:&A,s:u32,es:&[E])->u128{let mut m=0;for(t,&(i,j))in es.iter().enumerate(){if a[i]&a[j]==0 && (s>>i&s>>j&1)==0 && a[i].count_ones()+(s>>i&1)<7 && a[j].count_ones()+(s>>j&1)<7{m|=1<<t}}m}
fn dfs(a:&A,s:u32,es:&[E],ds:&[u128],sel:u128)->Option<u128>{let ok=avail(a,s,es);let mut best=None;for &d in ds{if sel&d!=0{continue}let t=d&ok;if t==0{return None}if best.map_or(true,|b:u128|t.count_ones()<b.count_ones()){best=Some(t)}}let mut m=match best{None=>return Some(sel),Some(t)=>t};if sel.count_ones()==7{return None}while m!=0{let k=m.trailing_zeros()as usize;m&=m-1;let(i,j)=es[k];let mut b=*a;b[i]|=1<<j;b[j]|=1<<i;if let Some(t)=dfs(&b,s,es,ds,sel|1<<k){return Some(t)}}None}
fn solve(mut a:A,cuts:[E;3])->Option<(u32,Vec<E>)>{for &(i,j) in &cuts{a[i]^=1<<j;a[j]^=1<<i}let mut es=vec![];for i in 0..26{for j in i+1..26{if a[i]&((1<<j)|a[j])==0&&!cuts.contains(&(i,j))&&a[i].count_ones()<7&&a[j].count_ones()<7{es.push((i,j))}}}assert!(es.len()<128);let mut sets=vec![0u32];for i in 0..26{for k in 0..sets.len(){if sets[k]&a[i]==0{sets.push(sets[k]|1<<i)}}}let mut permanent=vec![];let mut qs=vec![];for &q in &sets{let sz=q.count_ones();if sz!=7&&sz!=8{continue}let mut m=0;for(k,&(i,j))in es.iter().enumerate(){if q>>i&q>>j&1!=0{m|=1<<k}}if m==0{if sz==8{return None}permanent.push(q)}else{qs.push((if sz==7{q}else{0},m))}}let sat=(0..26).filter(|&i|a[i].count_ones()>=7).fold(0,|m,i|m|1<<i);for s in sets{if !(4..=7).contains(&s.count_ones())||s&sat!=0||permanent.iter().any(|q|q&s==0){continue}let ds:Vec<_>=qs.iter().filter(|(q,_)|q&s==0).map(|(_,m)|*m).collect();if let Some(t)=dfs(&a,s,&es,&ds,0){return Some((s,es.iter().enumerate().filter(|(k,_)|t>>k&1!=0).map(|(_,e)|*e).collect()))}}None}
fn main(){let mut st=String::new();io::stdin().read_to_string(&mut st).unwrap();let a:A=st.split_whitespace().map(|s|s.parse::<u32>().unwrap()).collect::<Vec<_>>().try_into().unwrap();let mut edges=vec![];for i in 0..26{for j in i+1..26{if a[i]>>j&1!=0{edges.push((i,j))}}}let mut jobs=vec![];for i in 0..edges.len(){for j in 0..i{for k in 0..j{jobs.push([edges[k],edges[j],edges[i]])}}}let pieces:Vec<_>=jobs.chunks((jobs.len()+7)/8).map(|x|{let v=x.to_vec();std::thread::spawn(move||{let mut n=0;for c in v{if let Some(w)=solve(a,c){println!("{:?} {:?}",c,w);n+=1}}n})}).collect();let n:usize=pieces.into_iter().map(|t|t.join().unwrap()).sum();println!("{} {}",jobs.len(),n)}
